solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
char *proverb(const char *const *x, size_t n, const char *q) {
    size_t cap = 1;
    for (size_t i = 0; i < n; i++)
        cap += 2 * strlen(x[i]) + 100;
    cap += q ? strlen(q) : 0;
    char *out = (char *)calloc(cap, 1);
    for (size_t i = 0; i + 1 < n; i++)
        sprintf(out + strlen(out), "For want of a %s the %s was lost.\n", x[i],
                x[i + 1]);
    if (n)
        sprintf(out + strlen(out), "And all for the want of a %s%s%s.", q ? q : "",
                q && *q ? " " : "", x[0]);
    return out;
}

