#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    const char *x[] = {"nail", "shoe", "horse"};
    char *s = proverb(x, 3, "horseshoe");
    assert(!strcmp(s, "For want of a nail the shoe was lost.\nFor want of a shoe the "
                      "horse was lost.\nAnd all for the want of a horseshoe nail."));
    free(s);
    s = proverb(NULL, 0, NULL);
    assert(!*s);
    free(s);

    return 0;
}
